<script setup>import{onMounted,ref}from'vue';import{studentApi,formatTime}from'../../api/student';const rows=ref([]),error=ref('');onMounted(async()=>{try{rows.value=(await studentApi.results()).data}catch(e){error.value=e.message}})</script><template><header class="page-heading"><div><p class="eyebrow">RESULTS</p><h1>我的成绩</h1><p class="muted">这里只展示教师已经发布的成绩。</p></div></header><p v-if="error" class="error-message">{{error}}</p><p v-if="!rows.length" class="empty-state">暂无已发布成绩。</p><div v-else class="course-grid"><article v-for="r in rows" :key="r.submissionId" class="surface result-card"><p class="eyebrow">{{formatTime(r.publishedAt)}} 发布</p><h3>{{r.examTitle}}</h3><strong class="score">{{r.totalScore}}</strong><p class="preserve">教师评语：{{r.teacherComment||'暂无评语'}}</p></article></div></template>
